void sort_values(int32_t a[], size_t n) {
    for (size_t end = n; end > 1; --end) {
        int changed = 0;
        for (size_t i = 0; i + 1 < end; ++i) {
            if (a[i] > a[i + 1]) {
                int32_t t = a[i]; a[i] = a[i + 1]; a[i + 1] = t;
                changed = 1;
            }
        }
        if (!changed) break;
    }
}

