#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>

/* Returns 1 on success, 0 if the buffer cannot be allocated. */
int sort_values(int32_t a[], size_t n) {
    if (n < 2) return 1;
    if (n > SIZE_MAX / sizeof(int32_t)) return 0;
    int32_t *buffer = malloc(n * sizeof(*buffer));
    if (!buffer) return 0;
    for (size_t width = 1; width < n; width *= 2) {
        for (size_t lo = 0; lo < n; lo += 2 * width) {
            size_t mid = lo + width < n ? lo + width : n;
            size_t hi = lo + 2 * width < n ? lo + 2 * width : n;
            size_t i = lo, j = mid;
            for (size_t k = lo; k < hi; ++k) {
                if (i < mid && (j >= hi || a[i] <= a[j]))
                    buffer[k] = a[i++];
                else buffer[k] = a[j++];
            }
            for (size_t k = lo; k < hi; ++k) a[k] = buffer[k];
        }
    }
    free(buffer);
    return 1;
}

