static void quick_range(int32_t a[], size_t lo, size_t hi) {
    if (lo >= hi) return;
    int32_t pivot = a[hi];
    size_t next = lo;
    for (size_t j = lo; j < hi; ++j) {
        if (a[j] <= pivot) {
            int32_t t = a[next]; a[next] = a[j]; a[j] = t;
            ++next;
        }
    }
    int32_t t = a[next]; a[next] = a[hi]; a[hi] = t;
    if (next > lo) quick_range(a, lo, next - 1);
    if (next < hi) quick_range(a, next + 1, hi);
}
void sort_values(int32_t a[], size_t n) {
    if (n > 1) quick_range(a, 0, n - 1);
}

