public final class QuickSort {
    private static void partitionSort(int[] a, int lo, int hi) {
        if (lo >= hi) return;
        int pivot = a[hi], next = lo;
        for (int j = lo; j < hi; j++) {
            if (a[j] <= pivot) {
                int t = a[next]; a[next] = a[j]; a[j] = t;
                next++;
            }
        }
        int t = a[next]; a[next] = a[hi]; a[hi] = t;
        partitionSort(a, lo, next - 1);
        partitionSort(a, next + 1, hi);
    }
    public static void sort(int[] a) {
        partitionSort(a, 0, a.length - 1);
    }
}

