static void sift(int32_t a[], size_t size, size_t root) {
    while (root < size / 2) {
        size_t largest = root, left = 2 * root + 1, right = left + 1;
        if (a[left] > a[largest]) largest = left;
        if (right < size && a[right] > a[largest]) largest = right;
        if (largest == root) return;
        int32_t t = a[root]; a[root] = a[largest]; a[largest] = t;
        root = largest;
    }
}
void sort_values(int32_t a[], size_t n) {
    for (size_t i = n / 2; i > 0; --i) sift(a, n, i - 1);
    for (size_t end = n; end > 1; --end) {
        int32_t t = a[0]; a[0] = a[end - 1]; a[end - 1] = t;
        sift(a, end - 1, 0);
    }
}

