#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>

/* Four stable byte passes; signed 32-bit integers, including negatives. */
int sort_values(int32_t a[], size_t n) {
    if (n < 2) return 1;
    if (n > SIZE_MAX / sizeof(int32_t)) return 0;
    int32_t *out = malloc(n * sizeof(*out));
    if (!out) return 0;
    for (unsigned shift = 0; shift < 32; shift += 8) {
        size_t count[256] = {0};
        for (size_t i = 0; i < n; ++i) {
            uint32_t key = (uint32_t)a[i] ^ UINT32_C(0x80000000);
            ++count[(key >> shift) & 255u];
        }
        for (size_t b = 1; b < 256; ++b) count[b] += count[b - 1];
        for (size_t i = n; i > 0; --i) {
            uint32_t key = (uint32_t)a[i - 1] ^ UINT32_C(0x80000000);
            out[--count[(key >> shift) & 255u]] = a[i - 1];
        }
        for (size_t i = 0; i < n; ++i) a[i] = out[i];
    }
    free(out);
    return 1;
}

