    for shift in range(0, 32, 8):
        count = [0] * 256
        for value in values:
            key = (value & 0xFFFFFFFF) ^ 0x80000000
            count[(key >> shift) & 255] += 1
        for b in range(1, 256):
            count[b] += count[b - 1]
        for i in range(len(values) - 1, -1, -1):
            key = (values[i] & 0xFFFFFFFF) ^ 0x80000000
            digit = (key >> shift) & 255
            count[digit] -= 1
            out[count[digit]] = values[i]
        values[:] = out

